/* harmony default export */ __webpack_exports__["default"] = ({
  onLoad(e) {
    this.type = e.type || '';
  },
  onShow() {
    this.options = [{
      text: '编辑',
      style: {
        backgroundColor: this.theme.bgColor
      }
    }, {
      text: '删除',
      style: {
        backgroundColor: '#dd524d'
      }
    }];
    if (this.isFirst && !this.vuex_token) {
      uni.$u.route({
        type: 'back',
        delta: 1
      });
      return;
    }
    this.isFirst = true;
    this.getAddressList();
  },
  data() {
    return {
      isFirst: false,
      list: [],
      disabled: false,
      btnWidth: 180,
      show: false,
      options: [],
      is_loading: true
    };
  },
  methods: {
    click(index, index1) {
      if (index1 == 1) {
        //删除
        this.$api.delAddress({
          id: this.list[index].id
        }).then(res => {
          this.$u.toast(res.msg);
          if (res.code) {
            if (this.vuex_address.id && this.vuex_address.id == this.list[index].id) {
              this.$u.vuex('vuex_address', {});
            }
            this.list.splice(index, 1);
          }
        });
      } else {
        //编辑
        this.goPage('/pages/address/addedit?id=' + this.list[index].id);
      }
    },
    // 如果打开一个的时候，不需要关闭其他，则无需实现本方法
    open(index) {
      // 先将正在被操作的swipeAction标记为打开状态，否则由于props的特性限制，
      // 原本为'false'，再次设置为'false'会无效
      this.list[index].show = true;
      this.list.map((val, idx) => {
        if (index != idx) this.list[idx].show = false;
      });
    },
    getAddressList() {
      this.$api.addressList({
        page: this.page
      }).then(res => {
        if (res.code) {
          this.list = res.data;
        }
        this.is_loading = false;
      });
    },
    //选择地址
    select(item) {
      if (this.type == 'select') {
        this.$u.vuex('vuex_address', item);
        uni.$u.route({
          type: 'back'
        });
      }
    }
  }
});

